//! Discrete Gaussian sampler for KAHE keys and errors.
//!
//! Samples `x ∈ Z` with probability proportional to `exp(−x²/(2σ²))`, with
//! `σ =` [`SIGMA`], by inversion: a cumulative distribution table of `|x|`
//! (`dgauss_table.rs`, generated by `scripts/params/dgauss_cdt.py`) and a uniform
//! sign. Each sample takes 192 uniform bits `u` and one sign bit, and `|x|` is
//! the number of thresholds `≤ u`, so `|x| ≤` [`MAX_ABS`]. The table's header
//! records the output's statistical distance from the discrete Gaussian.
//!
//! The sampler is constant time: every sample is compared with every threshold,
//! without branches or memory accesses that depend on it, and the sign is applied
//! arithmetically. An AVX2 kernel is chosen at run time where the CPU has it, and
//! a scalar kernel otherwise. The scalar kernel is written with masks, but Rust
//! doesn't guarantee that the compiler keeps it free of branches, and what it
//! does depends on the target (see [`opaque`]). `scripts/dgauss_branches.py`
//! checks the compiled kernels for branches on the sample.
//!
//! The kernels compare 192-bit numbers as words `(hi, mid, lo)`, using the
//! table's three tiers:
//! - Entries before `TIER1` have distinct high words below `u64::MAX`. `u ≥ T`
//!   iff `hi > T.hi`, or `hi = T.hi` and `(mid, lo) ≥ (T.mid, T.lo)`. At most one
//!   of them has `T.hi = hi`, so the scan selects that entry's `(mid, lo)` with
//!   masks, and one comparison after the scan settles it.
//! - Entries from `TIER1` to `TIER2` have high word `u64::MAX` and distinct middle
//!   words. They count only if `hi = u64::MAX`, by the same rule one word lower.
//! - Entries from `TIER2` on have high and middle words `u64::MAX`. They count
//!   only if both of `u`'s words are `u64::MAX`, and then iff `lo ≥ T.lo`.

#[path = "dgauss_table.rs"]
mod table;

use rand::RngCore;

use crate::{KahePoly, N};

pub(crate) use table::SIGMA;
use table::{TABLE, TIER1, TIER2};

/// Largest `|x|` the sampler outputs.
pub(crate) const MAX_ABS: i64 = TABLE.len() as i64;

/// Random bytes per sample: `u` as `lo`, `mid`, `hi`, little-endian, then the sign.
const BYTES: usize = 25;
/// Samples per kernel call.
const LANES: usize = 8;

/// The 192-bit numbers of up to `LANES` samples, as words.
#[derive(Default)]
struct Words {
    hi: [u64; LANES],
    mid: [u64; LANES],
    lo: [u64; LANES],
}

/// A polynomial with independent coefficients from the discrete Gaussian.
pub(crate) fn sample_poly<R: RngCore>(rng: &mut R) -> KahePoly {
    let mut coeffs = [0i64; N];
    sample(rng, &mut coeffs);
    KahePoly::from_coeffs(coeffs)
}

/// Fills `out` with independent samples, drawing 25 random bytes per sample.
pub(crate) fn sample<R: RngCore>(rng: &mut R, out: &mut [i64]) {
    let mut buf = [0u8; BYTES * LANES];
    for chunk in out.chunks_mut(LANES) {
        let bytes = &mut buf[..BYTES * chunk.len()];
        rng.fill_bytes(bytes);
        let (samples, _) = bytes.as_chunks::<BYTES>();
        let mut u = Words::default();
        for (k, b) in samples.iter().enumerate() {
            u.lo[k] = u64::from_le_bytes(b[0..8].try_into().unwrap());
            u.mid[k] = u64::from_le_bytes(b[8..16].try_into().unwrap());
            u.hi[k] = u64::from_le_bytes(b[16..24].try_into().unwrap());
        }
        let abs = count(&u);
        for ((c, b), a) in chunk.iter_mut().zip(samples).zip(abs) {
            // x = |x| or −|x|: (a ⊕ s) − s with s = 0 or −1
            let s = -i64::from(b[24] & 1);
            *c = (a ^ s) - s;
        }
    }
}

/// For each lane, the number of thresholds `≤ u`.
fn count(u: &Words) -> [i64; LANES] {
    #[cfg(target_arch = "x86_64")]
    {
        if is_x86_feature_detected!("avx2") {
            // SAFETY: the CPU has AVX2.
            return unsafe { count_avx2(u) };
        }
    }
    count_scalar(u)
}

/// `1` if `a > b`, else `0`: the borrow of `b − a`.
#[inline(always)]
fn gt(a: u64, b: u64) -> u64 {
    u64::from(b.overflowing_sub(a).1)
}

/// `1` if `a = b`, else `0`.
#[inline(always)]
fn eq(a: u64, b: u64) -> u64 {
    let d = a ^ b;
    ((d | d.wrapping_neg()) >> 63) ^ 1
}

/// All ones for `1`, zero for `0`.
#[inline(always)]
fn mask(bit: u64) -> u64 {
    bit.wrapping_neg()
}

/// `x`, hidden from the optimizer on x86-64. There, without it, LLVM turns the
/// masked selection in tier 1 into a branch on the sample. On aarch64, it
/// vectorizes the loop with NEON instead, which has no such branch, and a
/// barrier would prevent that.
#[inline(always)]
fn opaque(x: u64) -> u64 {
    #[cfg(target_arch = "x86_64")]
    {
        let mut y = x;
        // SAFETY: an empty instruction sequence; it only hides `y`'s value.
        unsafe {
            core::arch::asm!("/* {0} */", inout(reg) y, options(pure, nomem, nostack, preserves_flags));
        }
        y
    }
    #[cfg(not(target_arch = "x86_64"))]
    x
}

fn count_scalar(u: &Words) -> [i64; LANES] {
    let mut out = [0i64; LANES];
    for (k, o) in out.iter_mut().enumerate() {
        *o = count_one(u.hi[k], u.mid[k], u.lo[k]) as i64;
    }
    out
}

fn count_one(hi: u64, mid: u64, lo: u64) -> u64 {
    // Tier 1: count T.hi < hi, and select the entry with T.hi = hi, if any.
    let (mut n1, mut found, mut sel_mid, mut sel_lo) = (0u64, 0u64, 0u64, 0u64);
    for t in &TABLE[..TIER1] {
        n1 += gt(hi, t[0]);
        let e = opaque(mask(eq(hi, t[0])));
        found |= e;
        sel_mid |= e & t[1];
        sel_lo |= e & t[2];
    }
    let below = gt(sel_mid, mid) | (eq(sel_mid, mid) & gt(sel_lo, lo));
    n1 += found & 1 & (below ^ 1);

    // Tier 2, counted if hi = u64::MAX.
    let (mut n2, mut found2, mut sel2) = (0u64, 0u64, 0u64);
    for t in &TABLE[TIER1..TIER2] {
        n2 += gt(mid, t[1]);
        let e = opaque(mask(eq(mid, t[1])));
        found2 |= e;
        sel2 |= e & t[2];
    }
    n2 += found2 & 1 & (gt(sel2, lo) ^ 1);

    // Tier 3, counted if hi = mid = u64::MAX.
    let mut n3 = 0u64;
    for t in &TABLE[TIER2..] {
        n3 += gt(t[2], lo) ^ 1;
    }

    let top = mask(eq(hi, u64::MAX));
    let top2 = top & mask(eq(mid, u64::MAX));
    n1 + (top & n2) + (top2 & n3)
}

/// The table with every word's top bit flipped, so that AVX2's signed 64-bit
/// comparisons order the words as unsigned numbers.
#[cfg(target_arch = "x86_64")]
const FLIPPED: [[i64; 3]; TABLE.len()] = {
    let mut out = [[0i64; 3]; TABLE.len()];
    let mut i = 0;
    while i < TABLE.len() {
        let mut j = 0;
        while j < 3 {
            out[i][j] = (TABLE[i][j] ^ (1 << 63)) as i64;
            j += 1;
        }
        i += 1;
    }
    out
};

/// [`count_scalar`] with AVX2, as two groups of four lanes.
#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "avx2")]
unsafe fn count_avx2(u: &Words) -> [i64; LANES] {
    use std::arch::x86_64::*;

    let flip = _mm256_set1_epi64x(i64::MIN);
    let load = |a: &[u64; LANES], i: usize| {
        _mm256_xor_si256(_mm256_loadu_si256(a[i..].as_ptr() as *const __m256i), flip)
    };
    let (h0, h1) = (load(&u.hi, 0), load(&u.hi, 4));
    let (m0, m1) = (load(&u.mid, 0), load(&u.mid, 4));
    let (l0, l1) = (load(&u.lo, 0), load(&u.lo, 4));
    let zero = _mm256_setzero_si256();

    // Tier 1. Comparison results are −1 or 0, so subtracting them counts.
    let (mut n0, mut n1) = (zero, zero);
    let (mut f0, mut f1) = (zero, zero);
    let (mut sm0, mut sm1, mut sl0, mut sl1) = (zero, zero, zero, zero);
    for t in &FLIPPED[..TIER1] {
        let th = _mm256_set1_epi64x(t[0]);
        let tm = _mm256_set1_epi64x(t[1]);
        let tl = _mm256_set1_epi64x(t[2]);
        n0 = _mm256_sub_epi64(n0, _mm256_cmpgt_epi64(h0, th));
        n1 = _mm256_sub_epi64(n1, _mm256_cmpgt_epi64(h1, th));
        let e0 = _mm256_cmpeq_epi64(h0, th);
        let e1 = _mm256_cmpeq_epi64(h1, th);
        f0 = _mm256_or_si256(f0, e0);
        f1 = _mm256_or_si256(f1, e1);
        sm0 = _mm256_or_si256(sm0, _mm256_and_si256(e0, tm));
        sm1 = _mm256_or_si256(sm1, _mm256_and_si256(e1, tm));
        sl0 = _mm256_or_si256(sl0, _mm256_and_si256(e0, tl));
        sl1 = _mm256_or_si256(sl1, _mm256_and_si256(e1, tl));
    }
    let below = |sm, m, sl, l| {
        _mm256_or_si256(
            _mm256_cmpgt_epi64(sm, m),
            _mm256_and_si256(_mm256_cmpeq_epi64(sm, m), _mm256_cmpgt_epi64(sl, l)),
        )
    };
    n0 = _mm256_sub_epi64(n0, _mm256_andnot_si256(below(sm0, m0, sl0, l0), f0));
    n1 = _mm256_sub_epi64(n1, _mm256_andnot_si256(below(sm1, m1, sl1, l1), f1));

    // Tier 2.
    let (mut p0, mut p1) = (zero, zero);
    let (mut g0, mut g1, mut s0, mut s1) = (zero, zero, zero, zero);
    for t in &FLIPPED[TIER1..TIER2] {
        let tm = _mm256_set1_epi64x(t[1]);
        let tl = _mm256_set1_epi64x(t[2]);
        p0 = _mm256_sub_epi64(p0, _mm256_cmpgt_epi64(m0, tm));
        p1 = _mm256_sub_epi64(p1, _mm256_cmpgt_epi64(m1, tm));
        let e0 = _mm256_cmpeq_epi64(m0, tm);
        let e1 = _mm256_cmpeq_epi64(m1, tm);
        g0 = _mm256_or_si256(g0, e0);
        g1 = _mm256_or_si256(g1, e1);
        s0 = _mm256_or_si256(s0, _mm256_and_si256(e0, tl));
        s1 = _mm256_or_si256(s1, _mm256_and_si256(e1, tl));
    }
    p0 = _mm256_sub_epi64(p0, _mm256_andnot_si256(_mm256_cmpgt_epi64(s0, l0), g0));
    p1 = _mm256_sub_epi64(p1, _mm256_andnot_si256(_mm256_cmpgt_epi64(s1, l1), g1));

    // Tier 3: start at its size and subtract the entries with lo < T.lo.
    let size3 = _mm256_set1_epi64x((TABLE.len() - TIER2) as i64);
    let (mut q0, mut q1) = (size3, size3);
    for t in &FLIPPED[TIER2..] {
        let tl = _mm256_set1_epi64x(t[2]);
        q0 = _mm256_add_epi64(q0, _mm256_cmpgt_epi64(tl, l0));
        q1 = _mm256_add_epi64(q1, _mm256_cmpgt_epi64(tl, l1));
    }

    // u64::MAX with its top bit flipped.
    let top = _mm256_set1_epi64x(i64::MAX);
    let t0 = _mm256_cmpeq_epi64(h0, top);
    let t1 = _mm256_cmpeq_epi64(h1, top);
    let tt0 = _mm256_and_si256(t0, _mm256_cmpeq_epi64(m0, top));
    let tt1 = _mm256_and_si256(t1, _mm256_cmpeq_epi64(m1, top));
    n0 = _mm256_add_epi64(n0, _mm256_and_si256(t0, p0));
    n1 = _mm256_add_epi64(n1, _mm256_and_si256(t1, p1));
    n0 = _mm256_add_epi64(n0, _mm256_and_si256(tt0, q0));
    n1 = _mm256_add_epi64(n1, _mm256_and_si256(tt1, q1));

    let mut out = [0i64; LANES];
    _mm256_storeu_si256(out.as_mut_ptr() as *mut __m256i, n0);
    _mm256_storeu_si256(out[4..].as_mut_ptr() as *mut __m256i, n1);
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use rand::SeedableRng;
    use rand_chacha::ChaCha20Rng;

    /// The number of thresholds `≤ (hi, mid, lo)`, by plain comparison.
    fn reference(hi: u64, mid: u64, lo: u64) -> i64 {
        TABLE
            .iter()
            .filter(|t| (hi, mid, lo) >= (t[0], t[1], t[2]))
            .count() as i64
    }

    /// Runs both kernels on `inputs` and compares them with the reference.
    fn check_kernels(inputs: &[(u64, u64, u64)]) {
        for batch in inputs.chunks(LANES) {
            let mut u = Words::default();
            for (k, &(h, m, l)) in batch.iter().enumerate() {
                (u.hi[k], u.mid[k], u.lo[k]) = (h, m, l);
            }
            let want: Vec<i64> = (0..LANES)
                .map(|k| reference(u.hi[k], u.mid[k], u.lo[k]))
                .collect();
            assert_eq!(count_scalar(&u).to_vec(), want, "scalar, inputs {batch:x?}");
            #[cfg(target_arch = "x86_64")]
            if is_x86_feature_detected!("avx2") {
                let got = unsafe { count_avx2(&u) };
                assert_eq!(got.to_vec(), want, "avx2, inputs {batch:x?}");
            }
        }
    }

    /// The kernels rely on this structure; the script checks it too.
    #[test]
    fn table_has_the_tiers_the_kernels_rely_on() {
        assert!(TABLE
            .windows(2)
            .all(|w| (w[0][0], w[0][1], w[0][2]) < (w[1][0], w[1][1], w[1][2])));
        assert!(TABLE[..TIER1].iter().all(|t| t[0] < u64::MAX));
        assert!(TABLE[..TIER1].windows(2).all(|w| w[0][0] < w[1][0]));
        assert!(TABLE[TIER1..].iter().all(|t| t[0] == u64::MAX));
        assert!(TABLE[TIER1..TIER2].iter().all(|t| t[1] < u64::MAX));
        assert!(TABLE[TIER1..TIER2].windows(2).all(|w| w[0][1] < w[1][1]));
        assert!(TABLE[TIER2..].iter().all(|t| t[1] == u64::MAX));
    }

    /// Random inputs almost never reach the equality cases or the upper tiers, so
    /// every threshold is tested exactly, and with each word one above and below.
    #[test]
    fn kernels_count_thresholds_at_the_boundaries() {
        let mut inputs = vec![(0, 0, 0), (u64::MAX, u64::MAX, u64::MAX)];
        for t in TABLE {
            inputs.push((t[0], t[1], t[2]));
            for j in 0..3 {
                for d in [1u64, u64::MAX] {
                    let mut v = t;
                    v[j] = v[j].wrapping_add(d);
                    inputs.push((v[0], v[1], v[2]));
                }
            }
        }
        check_kernels(&inputs);
        assert_eq!(reference(u64::MAX, u64::MAX, u64::MAX), MAX_ABS);
        assert_eq!(reference(0, 0, 0), 0);
    }

    #[test]
    fn kernels_count_thresholds_for_random_inputs() {
        let mut rng = ChaCha20Rng::from_seed([1; 32]);
        let inputs: Vec<_> = (0..4096)
            .map(|_| (rng.next_u64(), rng.next_u64(), rng.next_u64()))
            .collect();
        check_kernels(&inputs);
    }

    /// A χ² test against the exact probabilities, one class per value with
    /// |x| ≤ 27 (at least 5 expected samples each) and one per tail.
    #[test]
    fn samples_follow_the_discrete_gaussian() {
        const SAMPLES: usize = 1 << 18;
        const CORE: i64 = 27;
        let mut rng = ChaCha20Rng::from_seed([2; 32]);
        let mut xs = vec![0i64; SAMPLES];
        sample(&mut rng, &mut xs);
        assert!(xs.iter().all(|x| x.abs() <= MAX_ABS));

        let weight = |x: i64| (-((x * x) as f64) / (2.0 * SIGMA * SIGMA)).exp();
        let total: f64 = (-200..=200).map(weight).sum();
        let p = |x: i64| weight(x) / total;
        let mut observed = vec![0f64; (2 * CORE + 3) as usize];
        let class = |x: i64| (x.clamp(-CORE - 1, CORE + 1) + CORE + 1) as usize;
        for &x in &xs {
            observed[class(x)] += 1.0;
        }
        let mut expected = vec![0f64; observed.len()];
        for x in -200i64..=200 {
            expected[class(x)] += p(x) * SAMPLES as f64;
        }
        let chi2: f64 = observed
            .iter()
            .zip(&expected)
            .map(|(o, e)| (o - e) * (o - e) / e)
            .sum();
        // 56 degrees of freedom; 104 is the 1 − 10⁻⁴ quantile.
        assert!(chi2 < 104.0, "χ² = {chi2:.1}");

        let n = SAMPLES as f64;
        let mean = xs.iter().sum::<i64>() as f64 / n;
        let var = xs.iter().map(|&x| (x * x) as f64).sum::<f64>() / n - mean * mean;
        let want_var: f64 = (-200i64..=200).map(|x| (x * x) as f64 * p(x)).sum();
        // Four standard errors: σ/√n for the mean, about σ²·√(2/n) for the variance.
        assert!(mean.abs() < 4.0 * SIGMA / n.sqrt(), "mean {mean}");
        assert!(
            (var - want_var).abs() < 4.0 * want_var * (2.0 / n).sqrt(),
            "variance {var}"
        );
    }

    /// A fixed seed gives fixed samples, so a change to the sampler shows up here.
    #[test]
    fn fixed_seed_gives_fixed_samples() {
        let mut xs = [0i64; 16];
        sample(&mut ChaCha20Rng::from_seed([0; 32]), &mut xs);
        assert_eq!(xs, KNOWN);
    }
    const KNOWN: [i64; 16] = [1, -4, -7, 1, -1, -4, 3, -3, -6, 11, 1, -1, 6, 0, 4, -5];
}
